{
  "message": "Migrate UserView to Pydantic v2 APIs while preserving dependency pins and the function signature.",
  "rationale": "ConfigDict enables attribute input, field-name population alongside the alias, and rejection of extra mapping fields. model_validate preserves required-field and integer validation with string coercion, while model_dump(by_alias=True) outputs id and displayName.",
  "files": [
    {
      "path": "src/integration.py",
      "content": "from pydantic import BaseModel, ConfigDict, Field


class UserView(BaseModel):
    model_config = ConfigDict(
        from_attributes=True,
        populate_by_name=True,
        extra="forbid",
    )

    id: int
    display_name: str = Field(alias="displayName")


def serialize_user(value):
    return UserView.model_validate(value).model_dump(by_alias=True)
